/**
 * ESLint plugin to auto-remove imports that are auto-imported by unplugin-auto-import
 *
 * Uses the dumpUnimportItems JSON file generated by unplugin-auto-import
 *
 * Compatible with both ESLint and OXC (oxlint)
 * - OXC: Uses createOnce for better performance
 * - ESLint: Uses standard create method
 */

import { readFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

// Get __dirname equivalent in ESM
const __dirname = dirname(fileURLToPath(import.meta.url))

// Load auto-imports config once (shared across all files)
let autoImports = null
let sourceToNames = null
let sourceToTypeNames = null

function loadAutoImports() {
  if (sourceToNames !== null)
    return true

  try {
    const configDir = __dirname
    const autoImportsPath = join(configDir, 'auto-imports.json')
    const content = readFileSync(autoImportsPath, 'utf-8')
    autoImports = JSON.parse(content)
  }
  catch {
    return false
  }

  if (!Array.isArray(autoImports)) {
    return false
  }

  // Build a map of source -> Set of auto-imported names
  sourceToNames = new Map()
  sourceToTypeNames = new Map()

  for (const item of autoImports) {
    if (!item.from || !item.name)
      continue

    const isType = item.type === true
    const source = item.from
    const name = item.as || item.name

    if (!sourceToNames.has(source)) {
      sourceToNames.set(source, new Set())
    }
    sourceToNames.get(source).add(name)

    if (isType) {
      if (!sourceToTypeNames.has(source)) {
        sourceToTypeNames.set(source, new Set())
      }
      sourceToTypeNames.get(source).add(name)
    }
  }

  return true
}

// Normalize import source for comparison
function normalizeSource(source) {
  if (source.startsWith('.'))
    return source
  if (source.startsWith('~'))
    return source.replace('~', '')
  if (source.startsWith('/'))
    return source
  return source
}

// Try to match a local import source against auto-import sources
function findMatchingAutoImportSource(importSource) {
  const normalized = normalizeSource(importSource)

  // Direct match
  if (sourceToNames.has(normalized)) {
    return normalized
  }

  // Try without file extension
  if (normalized.endsWith('.ts') || normalized.endsWith('.js')) {
    const withoutExt = normalized.replace(/\.(ts|js)$/, '')
    if (sourceToNames.has(withoutExt)) {
      return withoutExt
    }
  }

  // Try matching against project-relative paths in auto-imports.json
  for (const autoSource of sourceToNames.keys()) {
    if (!autoSource.includes('/weila-work-webview/src/'))
      continue

    const relativePath = autoSource.split('/src/')[1]
    const withoutExt = relativePath.replace(/\.(ts|js)$/, '')

    if (
      normalized === relativePath
      || normalized === `/${relativePath}`
      || normalized.endsWith(`/${relativePath}`)
      || normalized === withoutExt
      || normalized === `/${withoutExt}`
      || normalized.endsWith(`/${withoutExt}`)
      || normalized.includes(relativePath)
      || normalized.includes(withoutExt)
    ) {
      return autoSource
    }
  }

  return null
}

// Shared visitor factory - used by both create and createOnce
function createImportVisitor(context) {
  return {
    ImportDeclaration(node) {
      // Only process ES value imports (skip type imports)
      if (node.importKind === 'type')
        return

      const importSource = node.source.value

      if (typeof importSource !== 'string')
        return

      // Try to find matching auto-import source
      const matchedSource = findMatchingAutoImportSource(importSource)

      if (!matchedSource || !sourceToNames.has(matchedSource)) {
        return
      }

      const autoImportedNames = sourceToNames.get(matchedSource)

      // Analyze the import specifiers
      const autoImportedSpecifiers = []
      const manuallyImportedSpecifiers = []

      for (const specifier of node.specifiers) {
        if (specifier.type === 'ImportSpecifier') {
          const importedName = specifier.imported.name
          const localName = specifier.local.name

          if (autoImportedNames.has(importedName)) {
            autoImportedSpecifiers.push({
              importedName,
              localName,
              specifier,
            })
          }
          else {
            manuallyImportedSpecifiers.push({
              importedName,
              localName,
              specifier,
            })
          }
        }
        else if (specifier.type === 'ImportDefaultSpecifier') {
          const localName = specifier.local.name

          if (autoImportedNames.has('default')) {
            autoImportedSpecifiers.push({
              importedName: 'default',
              localName,
              specifier,
            })
          }
          else {
            manuallyImportedSpecifiers.push({
              importedName: 'default',
              localName,
              specifier,
            })
          }
        }
        else if (specifier.type === 'ImportNamespaceSpecifier') {
          const localName = specifier.local.name

          // Namespace imports are rarely auto-imported, skip them
          manuallyImportedSpecifiers.push({
            importedName: '*',
            localName,
            specifier,
          })
        }
      }

      // If all specifiers are auto-imported, remove the entire import
      if (autoImportedSpecifiers.length > 0 && manuallyImportedSpecifiers.length === 0) {
        const unnecessaryNames = autoImportedSpecifiers.map(s => s.importedName).join(', ')
        context.report({
          node,
          message: `Remove unnecessary import - auto-imported: ${unnecessaryNames}`,
          fix(fixer) {
            return fixer.remove(node)
          },
        })
      }
      // If some specifiers are auto-imported, remove only those
      else if (autoImportedSpecifiers.length > 0) {
        const unnecessaryNames = autoImportedSpecifiers.map(s => s.importedName).join(', ')
        for (const autoImport of autoImportedSpecifiers) {
          context.report({
            node: autoImport.specifier,
            message: `Remove auto-imported '{{name}}' (unnecessary: ${unnecessaryNames})`,
            data: { name: autoImport.importedName },
            fix(fixer) {
              if (node.specifiers.length === 1) {
                return fixer.remove(node)
              }

              const sourceCode = context.getSourceCode()
              const prevToken = sourceCode.getTokenBefore(autoImport.specifier)
              const nextToken = sourceCode.getTokenAfter(autoImport.specifier)

              const isOnlyNamedImport = node.specifiers.every(
                s => s.type === 'ImportSpecifier',
              )

              if (isOnlyNamedImport) {
                const specifierStart = autoImport.specifier.range[0]
                const specifierEnd = autoImport.specifier.range[1]

                let endOffset = 0
                if (nextToken && nextToken.value === ',') {
                  endOffset = nextToken.range[1] - specifierEnd
                }

                let startOffset = 0
                if (prevToken && prevToken.value !== '{') {
                  startOffset = specifierStart - prevToken.range[1]
                }

                return fixer.removeRange([
                  specifierStart - startOffset,
                  specifierEnd + endOffset,
                ])
              }
              else {
                return fixer.remove(autoImport.specifier)
              }
            },
          })
        }
      }
    },
  }
}

const noUnnecessaryImportRule = {
  meta: {
    type: 'suggestion',
    docs: {
      description: 'Disallow imports that are auto-imported',
      category: 'Best Practices',
      recommended: false,
    },
    fixable: 'code',
    hasSuggestions: false,
    schema: [],
  },
  // ESLint uses create
  create(context) {
    if (!loadAutoImports()) {
      return {}
    }
    return createImportVisitor(context)
  },
  // OXC uses createOnce for better performance
  createOnce(context) {
    return {
      before() {
        if (!loadAutoImports()) {
          return false
        }
      },
      ...createImportVisitor(context),
    }
  },
}

export default {
  meta: {
    name: 'eslint-plugin-auto-import-cleanup',
    version: '1.0.0',
  },
  rules: {
    'no-unnecessary-import': noUnnecessaryImportRule,
  },
}
